"""Build the four-mountain forecast-input ablation report from held-out scores."""
from pathlib import Path
import json,html
import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/nwp-weather'
SITES={'vail':'Vail sensor proxy','alta':'Alta–Collins','mansfield':'Mount Mansfield NOAA','jay':'Jay Peak NOAA'}
BASE='Historical calendar mean';FULL='+ wind forecasts'
LABELS={BASE:'Historical baseline','Calendar + ENSO':'Calendar + ENSO','+ precipitation forecasts':'+ precipitation','+ temperature forecasts':'+ temperature',FULL:'+ wind (full model)'}
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.15,'savefig.dpi':170})
def table(d):return d.to_html(index=False,border=0,float_format=lambda v:f'{v:.3f}',escape=True)

def skill_interval(pred,metric,draws=4000):
    b=pred[pred.model==BASE].set_index('row_id');f=pred[pred.model==FULL].set_index('row_id').reindex(b.index)
    if metric=='mse':lb=(b.predicted_inches-b.target_inches)**2;lf=(f.predicted_inches-f.target_inches)**2
    else:lb=(b.p_powder-(b.target_inches>=5))**2;lf=(f.p_powder-(f.target_inches>=5))**2
    a=pd.DataFrame({'winter':b.winter,'base':lb,'full':lf}).groupby('winter').sum();rng=np.random.default_rng(20261104);ix=rng.integers(0,len(a),(draws,len(a)))
    skill=1-a['full'].to_numpy()[ix].sum(1)/a['base'].to_numpy()[ix].sum(1)
    return float(1-lf.mean()/lb.mean()),float(np.quantile(skill,.025)),float(np.quantile(skill,.975))

def main():
    OUT.mkdir(exist_ok=True);summary=[];all_metrics=[];records={};plans=[]
    for route in ['mos','jma','jma-lead6']:
        for site,title in SITES.items():
            p=OUT/route/site
            if not (p/'crossvalidation_metrics.csv').exists():continue
            m=pd.read_csv(p/'crossvalidation_metrics.csv');c=pd.read_csv(p/'chronological_metrics.csv');pred=pd.read_csv(p/'crossvalidation_predictions.csv');plan=json.loads((p/'benchmark_plan.json').read_text())
            lead_label='6' if route=='jma-lead6' else 'all'
            if route=='jma-lead6':pred=pred[pred.lead_day==6].copy()
            a=m[m.leads.astype(str)==lead_label].set_index('model');cc=c[c.leads.astype(str)==lead_label].set_index('model')
            s,l,h=skill_interval(pred,'mse');bs,bl,bh=skill_interval(pred,'brier')
            r=dict(route=route,site=site,target=title,winters=int(a.loc[BASE,'winters']),scored_pairs=int(a.loc[BASE,'rows']),baseline_rmse=a.loc[BASE,'rmse'],full_rmse=a.loc[FULL,'rmse'],mse_skill=s,mse_skill_ci95_low=l,mse_skill_ci95_high=h,baseline_powder_brier=a.loc[BASE,'powder_brier'],full_powder_brier=a.loc[FULL,'powder_brier'],powder_brier_skill=bs,powder_skill_ci95_low=bl,powder_skill_ci95_high=bh,chrono_mse_skill=1-(cc.loc[FULL,'rmse']/cc.loc[BASE,'rmse'])**2,chrono_powder_skill=1-cc.loc[FULL,'powder_brier']/cc.loc[BASE,'powder_brier'])
            summary.append(r);mm=m.copy();mm.insert(0,'site',site);mm.insert(0,'route',route);all_metrics.append(mm);records[(route,site)]=(m,c,pred,plan)
            plans.append({'route':route,'site':site,'plan':plan})
    summary=pd.DataFrame(summary);summary.to_csv(OUT/'skill_summary.csv',index=False);pd.concat(all_metrics).to_csv(OUT/'all_metrics.csv',index=False)
    main_summary=summary[summary.route=='mos'].set_index('site').reindex(SITES)
    fig,axes=plt.subplots(1,2,figsize=(12,4.9))
    for ax,key,lo,hi,title in [(axes[0],'mse_skill','mse_skill_ci95_low','mse_skill_ci95_high','Daily snowfall MSE reduction'),(axes[1],'powder_brier_skill','powder_skill_ci95_low','powder_skill_ci95_high','Powder probability Brier-score improvement')]:
        y=np.arange(4);v=main_summary[key].to_numpy()*100;left=v-main_summary[lo].to_numpy()*100;right=main_summary[hi].to_numpy()*100-v
        ax.barh(y,v,color=['#64748b','#2563eb','#0d9488','#7c3aed'],alpha=.9);ax.errorbar(v,y,xerr=np.stack([left,right]),fmt='none',ecolor='#172554',capsize=4);ax.axvline(0,color='#111827',lw=1);ax.set_yticks(y,list(SITES.values()));ax.invert_yaxis();ax.set_title(title,fontweight='bold');ax.set_xlabel('Skill versus matched historical baseline (%)')
    fig.suptitle('Do archived weather forecasts help? · Four-mountain test',fontsize=15,fontweight='bold');fig.text(.5,.015,'Issued GFS MOS regional forecasts · First two future reporting days · Whole-winter cross-validation · 95% winter-bootstrap intervals',ha='center',fontsize=9);fig.tight_layout(rect=[0,.05,1,.94]);fig.savefig(OUT/'forecast_skill.png');fig.savefig(OUT/'forecast_skill.svg');plt.close(fig)
    fig,axes=plt.subplots(2,2,figsize=(13,8.2));names=list(LABELS)
    for ax,(site,title) in zip(axes.ravel(),SITES.items()):
        m=records[('mos',site)][0];a=m[m.leads.astype(str)=='all'].set_index('model');ref=a.loc[BASE,'powder_brier'];v=(1-a.loc[names,'powder_brier']/ref)*100
        ax.barh(np.arange(5),v,color=['#9ca3af','#94a3b8','#38bdf8','#0d9488','#2563eb']);ax.set_yticks(np.arange(5),[LABELS[n] for n in names]);ax.invert_yaxis();ax.axvline(0,color='black',lw=.8);ax.set_title(title,fontweight='bold');ax.set_xlabel('Powder-day probability skill versus history (%)')
    fig.suptitle('Add weather variables one step at a time',fontsize=16,fontweight='bold');fig.tight_layout(rect=[0,0,1,.95]);fig.savefig(OUT/'weather_ablation.png');plt.close(fig)
    fig,axes=plt.subplots(4,1,figsize=(13,10),sharex=False)
    for ax,(site,title) in zip(axes,SITES.items()):
        p=OUT/'mos'/site;d=pd.read_csv(p/'chronological_predictions.csv',parse_dates=['target_date']);year=int(d.winter.max());start=pd.Timestamp(year+1,1,1);end=start+pd.Timedelta(days=30);d=d[(d.lead_day==1)&d.target_date.between(start,end)]
        for name,color,alpha in [(BASE,'#6b7280',.5),(FULL,'#2563eb',1)]:
            r=d[d.model==name].sort_values('target_date');ax.plot(r.target_date,r.predicted_inches,color=color,alpha=alpha,lw=2,label=LABELS[name])
            if name==FULL:
                ax.fill_between(r.target_date,r.q10,r.q90,color=color,alpha=.12,label='Model 10–90% range');ax.plot(r.target_date,r.target_inches,'o-',color='#111827',lw=1,ms=3,label='Held-out observation')
        ax.set_title(f'{title} · January {year+1} chronological holdout',loc='left',fontweight='bold');ax.set_ylabel('Daily inches');ax.set_ylim(bottom=0);ax.xaxis.set_major_formatter(mdates.DateFormatter('%b %d'));ax.legend(ncol=4,fontsize=8,loc='upper right')
    fig.suptitle('Held-out daily predictions: weather forecasts can place storm peaks',fontsize=15,fontweight='bold');fig.tight_layout(rect=[0,0,1,.96]);fig.savefig(OUT/'heldout_daily_examples.png');plt.close(fig)
    current=[]
    for site,title in SITES.items():
        f=OUT/'mos'/site/'current_predictions.csv'
        if f.exists():
            d=pd.read_csv(f);d=d[d.model.isin([BASE,FULL])];d.insert(0,'target',title);current.append(d)
    current=pd.concat(current,ignore_index=True) if current else pd.DataFrame()
    if len(current):current.to_csv(OUT/'current_forecasts.csv',index=False)
    view=summary.copy();view['mse_skill_percent']=view.mse_skill*100;view['powder_skill_percent']=view.powder_brier_skill*100;view['chronological_mse_skill_percent']=view.chrono_mse_skill*100;view['chronological_powder_skill_percent']=view.chrono_powder_skill*100
    sections=[]
    for route in ['mos','jma','jma-lead6']:
        v=view[view.route==route]
        if len(v):
            label={'mos':'GFS MOS: first two future reporting days','jma':'JMA GSM: conservative daily leads1 and3','jma-lead6':'JMA GSM: supplementary day6 only'}[route]
            sections.append(f'<h3>{label}</h3>'+table(v[['target','winters','scored_pairs','baseline_rmse','full_rmse','mse_skill_percent','baseline_powder_brier','full_powder_brier','powder_skill_percent','chronological_mse_skill_percent','chronological_powder_skill_percent']]))
    detail=[]
    for (route,site),(m,c,pred,plan) in records.items():
        d=pd.read_csv(OUT/route/site/'matched_input.csv',parse_dates=['target_date'])
        detail.append(f'<h3>{route.upper()} · {SITES[site]}</h3><p>{len(d):,} matched forecast/target cases; {d.target_date.min().date()} through {d.target_date.max().date()}. Each forecast horizon is retained separately. <a href="{route}/{site}/crossvalidation_metrics.csv">Scores by lead</a> · <a href="{route}/{site}/chronological_metrics.csv">Chronological scores</a> · <a href="{route}/{site}/crossvalidation_paired.csv">Winter-bootstrap comparisons</a> · <a href="{route}/{site}/benchmark_plan.json">Splits and feature definitions</a></p>')
        detail.append(table(m[m.leads.astype(str)=='all'][['model','rmse','mae','crps','powder_brier','powder_observed_rate','powder_predicted_rate','coverage80']]))
    text='''<!doctype html><html><head><meta charset="utf-8"><title>Weather forecasts in mountain snowfall models</title><style>body{max-width:1150px;margin:40px auto;padding:0 24px;background:#fcfcfd;color:#17324d;font:16px/1.6 system-ui}h1,h2,h3{line-height:1.25}h2{margin-top:40px}img{width:100%;border:1px solid #e5e7eb;border-radius:8px}table{display:block;overflow-x:auto;border-collapse:collapse;font-size:13px;width:100%}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:right}td:first-child,th:first-child{text-align:left}a{color:#1d4ed8}.note{padding:18px;background:#eff6ff;border-left:4px solid #2563eb}</style></head><body><h1>Do weather forecasts improve mountain snowfall predictions?</h1><p>Vail, Alta–Collins, Mount Mansfield and Jay Peak · Experiment issued November 4, 2026.</p><div class="note">The primary comparison adds archived issued NOAA GFS station forecasts for precipitation, temperature/dewpoint and wind to a locally trained daily snowfall distribution. It compares the same held-out dates against a training-only historical calendar distribution. These are short-range tests; they do not establish day-specific forecast skill through December. Vail’s target remains a reported04:00 Sno24 sensor proxy rather than verified manual fresh snowfall.</div>'''
    text+='<h2>Primary result</h2><img src="forecast_skill.png" alt="Forecast skill compared with historical baseline"><p>Positive skill means lower error than the historical baseline; zero means equal performance. Snowfall skill is1−forecastMSE/baselineMSE. Powder skill is1−forecastBrier/baselineBrier, with a powder day defined as ≥5inches. Bars are the predeclared full weather model, not the best result selected after testing. Error bars resample whole winters4,000times. Small winter counts and overlapping cases limit precision; intervals are descriptive and do not account for all model/source choices.</p>'+''.join(sections)
    text+='<h2>What does each variable add?</h2><img src="weather_ablation.png" alt="Weather variable ablation"><p>The same empirical-distribution random forest is fitted with calendar+laggedENSO, then precipitation forecasts, then temperature/dewpoint, then wind. The QPF×coldness interaction first appears in the temperature step. A change between steps measures incremental predictive benefit for this model and feature set, not causation. The full feature model was fixed before evaluation.</p>'
    text+='<p>Precipitation provides the largest improvement in most cases. Temperature adds clear skill at Alta, Mansfield and Jay; its incremental Vail effect is uncertain. Wind adds evidence of lower snowfall MSE at Alta, Vail and Mansfield, but its additional powder-probability benefit is not consistently established. Jay’s added wind effect is uncertain. The main finding is the joint benefit of forecast weather, not a universal wind effect.</p><h2>How robust is the result?</h2><p>The full weather model improves both amount and powder probability in the separate chronological tests at all four sites. Reporting-clock tests use matched dates and the first fully future reporting day: Mansfield’s MSE reduction remains28–33%, Jay’s30–36%, and Vail’s46–50%. Excluding NOAA P-presumed-zero entries from scoring also retains the forecast benefit at both Vermont sites; this is an evaluation-only sensitivity, not a refit without presumed zeros.</p><p><a href="clock_sensitivity_summary.csv">Clock sensitivity results</a> · <a href="noaa_flag_sensitivity_metrics.csv">NOAA presumed-zero sensitivity</a> · <a href="noaa_flag_sensitivity_paired.csv">Presumed-zero paired comparisons</a></p><p>At the supplementary six-day horizon, Alta retains improvement in this small four-winter sample. Vail’s five-winter six-day confidence intervals include no improvement. This does not establish daily skill at six weeks or through the end of2026.</p>'
    text+='<h2>Forecasts on withheld winters</h2><img src="heldout_daily_examples.png" alt="Daily predictions against observations"><p>These January panels use the latest chronological holdout winter at each site and the first fully future reporting day. They are illustrations; the performance claims use every scored case. The predictive bands are empirical model distributions and are not independently calibrated.</p>'
    if len(current):
        current_view=current[current.model==FULL][['target','issue_time_utc','target_date','predicted_inches','q10','q90','p_powder']].copy();current_view['powder_probability_percent']=current_view.pop('p_powder')*100
        text+='<h2>Current short-range forecast</h2><p>Refitted models use the November4 00UTC GFS MOS forecast, assumed available at06UTC. Values are calibrated to the historical target stations; the Vermont station targets are not converted to resort summit totals. The daily ranges are uncalibrated and must not be added to form a cumulative range.</p>'+table(current_view)+'<p><a href="current_forecasts.csv">Current predictions including historical baseline</a></p>'
    text+='<h2>Sources and information boundaries</h2><ul><li><b>Common four-site archive:</b> NOAA operational GFS MOS archived by Iowa State, beginning inDecember2003. We downloaded actual forecast run/valid-time records and retained their raw encodings. All main cases use00UTC runs, a6-hour publication buffer, and complete forecast windows before+72hours. “Day1/2” denotes the first/second fully future reporting day; exact endpoint leads differ by station clock. Actual historical receipt timestamps are unavailable.</li><li><b>Regional reference points:</b> Vail uses Leadville/KLXV (about44kmaway); Alta uses Salt Lake City/KSLC (36km); Mansfield and Jay use Morrisville/KMVL (16km/46km). Airport temperatures and winds are regional predictors, not measured mountain weather. Site-specific calibration learns their relationship to the target.</li><li><b>Precipitation encoding:</b> GFS MOSP06 is a6-hour probability; Q06 is a categorical liquid-QPF amount. Categories remain ordinal inputs, never re-labelled as millimetres. Six-hour windows are weighted by their overlap with the24-hour target interval. The weighted meanPoP is a feature, not the daily probability of precipitation.</li><li><b>Recent gridded archive:</b> JMA GSM from Open-Meteo Previous Runs, approximately0.5°/55km, provides forecast precipitation amounts, temperature and winds. It is a fixed-lead hourly archive assembled from multiple runs, not a single coherent forecast initialization. Conservative offset-to-issue rules leave a24-hour buffer; missing early long-lead records remain missing. Its overlapping years differ from MOS, so scores across these archives are not an apples-to-apples model ranking.</li><li><b>Target alignment:</b> Alta’s manual snowfall window ends04:00local standardtime (11UTC). Vail’s04:00sourceclock is interpreted asMST with±1hour sensitivity. NOAA observation-time metadata are blank for Mansfield/Jay; main assumptions are16EST/21UTC for Mansfield and07:30EST/12:30UTC for Jay, with±6hour sensitivity. Jay’s clock is documented for1995, not verified day-by-day throughout training. The clock uncertainty limits day-specific claims.</li><li><b>Targets:</b> retain the prior manualAlta, NOAA Mansfield/Jay and provisionalCAICVail definitions. Quality-flagged NOAA observations are excluded;Ppresumedzeros are included as supplied. Other missing targets are never filled with zero. No resort website totals or resort multipliers enter fitting.</li></ul>'
    text+='<h2>Validation and model</h2><p>Each mountain has its own128-tree empirical-distribution forest (maximumdepth7, minimumleaf15). Hyperparameters are fixed; no best-test configuration is selected. Leaf outcomes come only from training winters, providing mutually consistent expected snowfall, powder probabilities, quantiles andCRPS. Models are compared on identical observed forecast/target cases. Shuffled three-fold validation holds out entire winters; a separate chronological test holds out the latest quarter of winters. Vail retains the six eligible winters from its earlier experiment; its chronological holdout contains only one winter, which limits conclusions about year-to-year robustness. Current winter2026/27 is excluded from evaluation.</p><p>Historical climatology pools unique observation dates in training winters within±15calendar days. Revised laggedRONI is available to the calibrated models, so this is not a fully historical-vintage ENSO test. The forecast weather itself is archived guidance, not realized future observations or reanalysis. Changes in operational forecast models over the archive and stale Vermont snowfall records remain limits.</p>'+''.join(detail)
    text+='<h2>Downloads and source documentation</h2><p><a href="skill_summary.csv">Summary and confidence limits</a> · <a href="all_metrics.csv">All lead-specific metrics</a> · <a href="../nwp-weather/validation_summary.json">Validation summary</a></p><ul>'+''.join(f'<li><a href="{u}">{l}</a></li>' for u,l in [('https://mesonet.agron.iastate.edu/mos/','Iowa State operationalMOS archive'),('https://mesonet.agron.iastate.edu/cgi-bin/request/mos.py?help','MOS archive API'),('https://vlab.noaa.gov/documents/6609493/36173388/mdltpb05-03.pdf','NOAA GFS MOS technical documentation'),('https://open-meteo.com/en/docs/previous-runs-api','Open-Meteo Previous Runs documentation'),('https://open-meteo.com/en/docs/jma-api','JMA forecast variables and processing'),('https://hive.utah.edu/records/280qy-4ee96','University of Utah Alta–Collins manual observations'),('https://www.ncei.noaa.gov/pub/data/ghcn/daily/readme-by_station.txt','NOAA observation-time metadata definition')])+'</ul><p>Source snapshots, URLs, hashes, raw flags, exact feature intervals, model checkpoints and held-out predictions are retained in the accompanying project. Third-party weather data retain their respective attribution/licensing terms.</p></body></html>'
    (OUT/'report.html').write_text(text)
    print(summary.to_string(index=False))
if __name__=='__main__':main()
